using System;
using UnityEngine;
using InControl;
using Game.Input;
using Framework.Save.Integrations.EasySave;

namespace Game.Tests
{
    /// <summary>
    /// GameInputManagerのキー設定保存機能を検証する。
    ///
    /// テスト専用のManagerと保存ファイルを生成し、
    /// 本番のキー設定に影響を与えないようにする。
    /// </summary>
    public class InputBindingSaveTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト設定")]

        /// <summary>開始時に自動テストを実行するか。</summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        #endregion

        #region Runtime Fields

        /// <summary>テスト専用のGameObject。</summary>
        private GameObject testObject;

        /// <summary>テスト対象の入力管理クラス。</summary>
        private GameInputManager inputManager;

        /// <summary>テスト専用の保存Provider。</summary>
        private EasySaveProvider saveProvider;

        /// <summary>成功したテスト項目数。</summary>
        private int passedCount;

        /// <summary>失敗したテスト項目数。</summary>
        private int failedCount;

        /// <summary>保存イベントの発生回数。</summary>
        private int savedEventCount;

        /// <summary>設定変更イベントの発生回数。</summary>
        private int changedEventCount;

        #endregion

        #region Unity Methods

        /// <summary>シーン開始時の処理。</summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Test Control Methods

        /// <summary>すべての自動テストを実行する。</summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;
            savedEventCount = 0;
            changedEventCount = 0;

            try
            {
                CreateTestObjects();

                TestInitialization();
                TestCaptureBindings();
                TestSaveBindings();
                TestModifiedBindings();
                TestLoadBindings();
                TestApplyBindings();
                TestResetBindings();
                TestInvalidData();
                TestPersistence();
                TestDeleteBindings();
                TestShutdown();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                CleanupTestObjects();
                PrintTestResult();
            }
        }

        /// <summary>
        /// テスト専用の保存ProviderとManagerを生成する。
        /// </summary>
        private void CreateTestObjects()
        {
            string testId =
                Guid.NewGuid().ToString("N");

            saveProvider = new EasySaveProvider(
                $"Tests/InputBindings_{testId}.es3");

            testObject = new GameObject(
                "InputBindingSaveTest_Manager");

            // Awakeによる通常初期化を遅らせる。
            testObject.SetActive(false);

            inputManager =
                testObject.AddComponent<GameInputManager>();

            // 本番とは異なる保存Providerを使用する。
            if (!inputManager.Initialize(saveProvider, false))
            {
                throw new InvalidOperationException(
                    "テスト用Managerの初期化に失敗しました。");
            }

            inputManager.BindingsSaved += OnBindingsSaved;
            inputManager.BindingsChanged += OnBindingsChanged;

            // Awakeが実行されても初期化済みなので、
            // 保存Providerは変更されない。
            testObject.SetActive(true);

            Debug.Log(
                $"テスト用保存先：{saveProvider.FilePath}",
                this);
        }

        /// <summary>
        /// テスト専用オブジェクトと保存ファイルを解放する。
        /// </summary>
        private void CleanupTestObjects()
        {
            if (inputManager != null)
            {
                inputManager.BindingsSaved -=
                    OnBindingsSaved;

                inputManager.BindingsChanged -=
                    OnBindingsChanged;

                inputManager.Shutdown();
                inputManager = null;
            }

            if (testObject != null)
            {
                testObject.SetActive(false);
                Destroy(testObject);

                testObject = null;
            }

            if (saveProvider != null)
            {
                try
                {
                    saveProvider.DeleteAll();
                }
                catch (Exception exception)
                {
                    failedCount++;

                    Debug.LogException(exception, this);
                }

                saveProvider = null;
            }
        }

        #endregion

        #region Test Methods

        /// <summary>初期化状態を検証する。</summary>
        private void TestInitialization()
        {
            Check(
                inputManager.IsInitialized,
                "入力システムの初期化");

            Check(
                inputManager.HasSaveProvider,
                "保存Providerの設定");

            Check(
                inputManager.ActionCount == 17,
                "操作登録数の維持");

            Check(
                !inputManager.HasSavedBindings(),
                "初期状態の保存データ未作成");

            Check(
                inputManager.LoadBindings(),
                "未保存状態での読み込み");
        }

        /// <summary>キー設定の取得処理を検証する。</summary>
        private void TestCaptureBindings()
        {
            InputBindingSaveData data =
                inputManager.CaptureBindings();

            Check(
                data != null,
                "キー設定データの生成");

            Check(
                data.IsSupportedVersion(),
                "保存バージョンの確認");

            Check(
                data.IsValid(),
                "保存データの有効性");

            Check(
                !string.IsNullOrWhiteSpace(
                    data.GameplayBindings),
                "ゲーム操作の保存文字列");

            Check(
                !string.IsNullOrWhiteSpace(
                    data.UIBindings),
                "UI操作の保存文字列");
        }

        /// <summary>キー設定の保存を検証する。</summary>
        private void TestSaveBindings()
        {
            savedEventCount = 0;

            Check(
                inputManager.SaveBindings(),
                "キー設定の保存");

            Check(
                inputManager.HasSavedBindings(),
                "保存済み設定の存在確認");

            Check(
                saveProvider.FileExists(),
                "ES3保存ファイルの生成");

            Check(
                savedEventCount == 1,
                "保存イベントの発生");

            Check(
                saveProvider.TryLoad<InputBindingSaveData>(
                    "InputBindings",
                    out InputBindingSaveData data) &&
                data != null &&
                data.IsValid(),
                "ES3からの保存データ直接取得");
        }

        /// <summary>
        /// キー割り当て変更後の保存を検証する。
        /// </summary>
        private void TestModifiedBindings()
        {
            InputBindingSaveData original =
                inputManager.CaptureBindings();

            // アイテム使用操作を取得する。
            bool found = inputManager.TryGetPlayerAction(
                GameInputAction.UseItem,
                out PlayerAction action);

            Check(
                found && action != null,
                "変更対象の操作取得");

            if (!found || action == null)
            {
                return;
            }

            // テスト用に既存の割り当てを削除する。
            action.ClearBindings();

            // 通常のSpaceからF8へ変更する。
            action.AddBinding(
                new KeyBindingSource(Key.F8));

            InputBindingSaveData modified =
                inputManager.CaptureBindings();

            Check(
                modified.GameplayBindings !=
                original.GameplayBindings,
                "変更後の保存文字列");

            Check(
                inputManager.SaveBindings(),
                "変更済みキー設定の保存");

            Check(
                saveProvider.TryLoad<InputBindingSaveData>(
                    "InputBindings",
                    out InputBindingSaveData saved) &&
                AreBindingsEqual(modified, saved),
                "変更済みキー設定の保存内容");
        }

        /// <summary>保存済みキー設定の復元を検証する。</summary>
        private void TestLoadBindings()
        {
            InputBindingSaveData expected =
                saveProvider.Load<InputBindingSaveData>(
                    "InputBindings",
                    null);

            inputManager.ResetBindings();

            Check(
                !AreBindingsEqual(
                    expected,
                    inputManager.CaptureBindings()),
                "初期化による現在の設定変更");

            changedEventCount = 0;

            Check(
                inputManager.LoadBindings(),
                "保存済みキー設定の復元");

            Check(
                AreBindingsEqual(
                    expected,
                    inputManager.CaptureBindings()),
                "復元後のキー設定一致");

            Check(
                changedEventCount == 1,
                "復元イベントの発生");
        }

        /// <summary>
        /// 一時退避したキー設定の適用を検証する。
        /// </summary>
        private void TestApplyBindings()
        {
            InputBindingSaveData backup =
                inputManager.CaptureBindings();

            inputManager.ResetBindings();

            Check(
                inputManager.ApplyBindings(backup),
                "退避したキー設定の適用");

            Check(
                AreBindingsEqual(
                    backup,
                    inputManager.CaptureBindings()),
                "適用後のキー設定一致");

            Check(
                inputManager.IsInputBlocked,
                "設定適用フレームの入力遮断");
        }

        /// <summary>キー設定の初期化を検証する。</summary>
        private void TestResetBindings()
        {
            InputBindingSaveData saved =
                saveProvider.Load<InputBindingSaveData>(
                    "InputBindings",
                    null);

            changedEventCount = 0;

            Check(
                inputManager.ResetBindings(),
                "キー設定の初期化");

            Check(
                changedEventCount == 1,
                "初期化イベントの発生");

            Check(
                !AreBindingsEqual(
                    saved,
                    inputManager.CaptureBindings()),
                "初期設定への変更");

            Check(
                inputManager.HasSavedBindings(),
                "初期化後の保存データ維持");

            Check(
                AreBindingsEqual(
                    saved,
                    saveProvider.Load<InputBindingSaveData>(
                        "InputBindings",
                        null)),
                "初期化による保存データ変更の防止");
        }

        /// <summary>無効な保存データを検証する。</summary>
        private void TestInvalidData()
        {
            InputBindingSaveData original =
                inputManager.CaptureBindings();

            Check(
                !inputManager.ApplyBindings(null),
                "null保存データの拒否");

            Check(
                !inputManager.ApplyBindings(
                    new InputBindingSaveData()),
                "空の保存データの拒否");

            InputBindingSaveData invalidVersion =
                inputManager.CaptureBindings();

            invalidVersion.Version =
                InputBindingSaveData.CurrentVersion + 1;

            Check(
                !inputManager.ApplyBindings(invalidVersion),
                "未対応バージョンの拒否");

            Check(
                AreBindingsEqual(
                    original,
                    inputManager.CaptureBindings()),
                "無効データ適用時の設定維持");

            // 未対応バージョンをテストファイルへ保存する。
            InputBindingSaveData saved =
                saveProvider.Load<InputBindingSaveData>(
                    "InputBindings",
                    null);

            try
            {
                saveProvider.Save(
                    "InputBindings",
                    invalidVersion);

                Check(
                    !inputManager.LoadBindings(),
                    "未対応保存データの読み込み拒否");

                Check(
                    AreBindingsEqual(
                        original,
                        inputManager.CaptureBindings()),
                    "読み込み失敗時の現在設定維持");
            }
            finally
            {
                // 後続テストのため正常な保存データへ戻す。
                saveProvider.Save(
                    "InputBindings",
                    saved);
            }
        }

        /// <summary>
        /// 入力システム再初期化後の復元を検証する。
        /// </summary>
        private void TestPersistence()
        {
            InputBindingSaveData expected =
                saveProvider.Load<InputBindingSaveData>(
                    "InputBindings",
                    null);

            inputManager.Shutdown();

            Check(
                !inputManager.IsInitialized,
                "再初期化前の終了処理");

            // 保存Providerも新しく生成する。
            saveProvider =
                new EasySaveProvider(saveProvider.FilePath);

            Check(
                inputManager.Initialize(
                    saveProvider,
                    true),
                "保存設定付きの再初期化");

            Check(
                inputManager.HasSavedBindings(),
                "再初期化後の保存データ存在確認");

            Check(
                AreBindingsEqual(
                    expected,
                    inputManager.CaptureBindings()),
                "再初期化後のキー設定復元");
        }

        /// <summary>保存データの削除を検証する。</summary>
        private void TestDeleteBindings()
        {
            InputBindingSaveData current =
                inputManager.CaptureBindings();

            // 同じファイル内に削除対象外のデータを作成する。
            saveProvider.Save("KeepData", 123);

            Check(
                inputManager.DeleteSavedBindings(),
                "保存済みキー設定の削除");

            Check(
                !inputManager.HasSavedBindings(),
                "削除後の保存データ消失");

            Check(
                AreBindingsEqual(
                    current,
                    inputManager.CaptureBindings()),
                "削除後の現在設定維持");

            Check(
                saveProvider.Load("KeepData", 0) == 123,
                "削除対象外のデータ維持");

            Check(
                inputManager.DeleteSavedBindings(),
                "未保存状態での削除");

            Check(
                inputManager.LoadBindings(),
                "削除後の読み込み");

            Check(
                inputManager.SaveBindings(),
                "削除後の再保存");
        }

        /// <summary>終了処理後の保存制御を検証する。</summary>
        private void TestShutdown()
        {
            inputManager.Shutdown();

            Check(
                !inputManager.HasSaveProvider,
                "終了後のProvider参照解除");

            Check(
                !inputManager.SaveBindings(),
                "終了後の保存拒否");

            Check(
                !inputManager.LoadBindings(),
                "終了後の読み込み拒否");

            Check(
                !inputManager.DeleteSavedBindings(),
                "終了後の削除拒否");

            Check(
                saveProvider.Exists("InputBindings"),
                "終了後の保存データ維持");
        }

        #endregion

        #region Event Methods

        /// <summary>保存イベントの発生回数を記録する。</summary>
        private void OnBindingsSaved()
        {
            savedEventCount++;
        }

        /// <summary>変更イベントの発生回数を記録する。</summary>
        private void OnBindingsChanged()
        {
            changedEventCount++;
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 2つのキー割り当てデータが一致するか確認する。
        /// </summary>
        /// <param name="first">比較元のデータ</param>
        /// <param name="second">比較先のデータ</param>
        /// <returns>一致する場合はtrue</returns>
        private static bool AreBindingsEqual(
            InputBindingSaveData first,
            InputBindingSaveData second)
        {
            if (first == null || second == null)
            {
                return false;
            }

            return first.Version == second.Version &&
                   first.GameplayBindings ==
                   second.GameplayBindings &&
                   first.UIBindings ==
                   second.UIBindings;
        }

        /// <summary>テスト結果を記録する。</summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>テストの集計結果を出力する。</summary>
        private void PrintTestResult()
        {
            string message =
                "【InputBindingSave テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
